app = ROOT / "src/devclean/ui/app.py"
replace_once(
    app,
    '''def scan_targets(\n    known_roots: Sequence[KnownCleanupRoot],\n    drives: Sequence[Path] = (),\n    rules: UserRules | None = None,\n) -> tuple[Path, ...]:\n    """Return the configured profile, catalog, and additional scan roots.\n\n    Defaults cover every catalog root the machine actually has, plus the profile\n    so project build output is reachable.  User exclusions and additional roots\n    are applied, then the result is reduced to outermost paths so nothing is\n    walked twice.  Whole drives are deliberately not walked.\n    """\n\n    active_rules = rules or default_rules()\n    candidates: list[Path] = []\n    profile = os.environ.get("USERPROFILE")\n    if profile and active_rules.scan.include_user_profile:\n        candidates.append(Path(profile))\n    if active_rules.scan.include_known_cleanup_roots:\n        candidates.extend(root.path for root in known_roots)\n    candidates.extend(expanded_scan_paths(active_rules.scan.additional_paths))\n    excluded = tuple(\n        normalise_path(path) for path in expanded_scan_paths(active_rules.scan.excluded_paths)\n    )\n    if drives:\n        allowed = {str(drive)[:2].casefold() for drive in drives}\n        candidates = [path for path in candidates if str(path)[:2].casefold() in allowed]\n    resolved: list[Path] = []\n    for path in candidates:\n        normalized_text = normalise_path(path)\n        if any(\n            normalized_text == blocked\n            or normalized_text.startswith(blocked.rstrip(os.sep) + os.sep)\n            for blocked in excluded\n        ):\n            continue\n        try:\n            if not path.is_dir():\n                continue\n        except OSError:\n            continue\n        normalized = Path(os.path.normcase(os.path.normpath(os.path.abspath(path))))\n        if any(normalized.is_relative_to(kept) for kept in resolved):\n            continue\n        resolved = [kept for kept in resolved if not kept.is_relative_to(normalized)]\n        resolved.append(normalized)\n    return tuple(resolved)\n''',
    '''def _scan_specific_roots(\n    known_roots: Sequence[KnownCleanupRoot],\n    rules: UserRules,\n) -> tuple[Path, ...]:\n    """Return roots whose exact selection must survive broad-name pruning."""\n\n    roots = list(expanded_scan_paths(rules.scan.additional_paths))\n    if rules.scan.include_known_cleanup_roots:\n        roots.extend(root.path for root in known_roots if root.application_rule is not None)\n    return tuple(dict.fromkeys(roots))\n\n\ndef _scan_path_excluded(path: Path, excluded: tuple[str, ...]) -> bool:\n    normalized = normalise_path(path)\n    return any(\n        normalized == blocked or normalized.startswith(blocked.rstrip(os.sep) + os.sep)\n        for blocked in excluded\n    )\n\n\ndef _scan_root_can_reach(\n    root: Path,\n    target: Path,\n    skip_directory_names: frozenset[str],\n) -> bool:\n    """Return whether normal traversal from *root* can reach *target*."""\n\n    try:\n        relative = target.relative_to(root)\n    except ValueError:\n        return False\n    if not relative.parts:\n        return True\n    return not any(part.casefold() in skip_directory_names for part in relative.parts)\n\n\ndef _scan_root_skip_name_overrides(\n    roots: Sequence[Path],\n    known_roots: Sequence[KnownCleanupRoot],\n    rules: UserRules,\n) -> frozenset[str]:\n    """Return exact selected roots allowed to bypass only their own skip-name."""\n\n    selected = {normalise_path(path) for path in roots}\n    return frozenset(\n        normalise_path(path)\n        for path in _scan_specific_roots(known_roots, rules)\n        if normalise_path(path) in selected\n    )\n\n\ndef scan_targets(\n    known_roots: Sequence[KnownCleanupRoot],\n    drives: Sequence[Path] = (),\n    rules: UserRules | None = None,\n) -> tuple[Path, ...]:\n    """Return broad roots plus otherwise unreachable explicit/audited roots.\n\n    The profile remains the cheap broad traversal root, but its skip-name rules\n    must not make an explicit user ``additional_path`` or source-audited\n    application root disappear. A specific nested root is therefore retained\n    only when every broader retained root would prune a component on the way to\n    it. Whole drives are deliberately never added.\n    """\n\n    active_rules = rules or default_rules()\n    candidates: list[Path] = []\n    profile = os.environ.get("USERPROFILE")\n    if profile and active_rules.scan.include_user_profile:\n        candidates.append(Path(profile))\n    if active_rules.scan.include_known_cleanup_roots:\n        candidates.extend(root.path for root in known_roots)\n    candidates.extend(expanded_scan_paths(active_rules.scan.additional_paths))\n    excluded = tuple(\n        normalise_path(path) for path in expanded_scan_paths(active_rules.scan.excluded_paths)\n    )\n    allowed = {str(drive)[:2].casefold() for drive in drives} if drives else None\n\n    def usable(path: Path) -> Path | None:\n        if allowed is not None and str(path)[:2].casefold() not in allowed:\n            return None\n        if _scan_path_excluded(path, excluded):\n            return None\n        try:\n            if not path.is_dir():\n                return None\n        except OSError:\n            return None\n        return Path(os.path.normcase(os.path.normpath(os.path.abspath(path))))\n\n    resolved: list[Path] = []\n    for path in candidates:\n        normalized = usable(path)\n        if normalized is None:\n            continue\n        if any(normalized.is_relative_to(kept) for kept in resolved):\n            continue\n        resolved = [kept for kept in resolved if not kept.is_relative_to(normalized)]\n        resolved.append(normalized)\n\n    skip_names = frozenset(name.casefold() for name in active_rules.scan.skip_directory_names)\n    specifics = sorted(\n        (normalized for path in _scan_specific_roots(known_roots, active_rules) if (normalized := usable(path)) is not None),\n        key=lambda path: len(path.parts),\n    )\n    for specific in specifics:\n        if any(_scan_root_can_reach(root, specific, skip_names) for root in resolved):\n            continue\n        resolved.append(specific)\n    return tuple(dict.fromkeys(resolved))\n''',
)
replace_once(
    app,
    '''                    skip_paths=frozenset(configured_skip_paths),\n                ),\n''',
    '''                    skip_paths=frozenset(configured_skip_paths),\n                    root_skip_name_overrides=_scan_root_skip_name_overrides(\n                        roots, known_roots, active_rules\n                    ),\n                ),\n''',
)

new_test = ROOT / "tests/test_scan_pruning_boundaries.py"
new_test.write_text('''from __future__ import annotations\n\nfrom dataclasses import replace\nfrom pathlib import Path\n\nfrom devclean.core.application_cleanup import (\n    ApplicationCleanupRule,\n    DecisionOwner,\n    LastUseStrategy,\n    MatchKind,\n    RebuildCost,\n)\nfrom devclean.core.cleanup_catalog import CleanupCategory, CleanupPolicy, KnownCleanupRoot\nfrom devclean.core.user_rules import UserRules, default_rules\nfrom devclean.scanner.filesystem import ScanOptions, ScanRecordKind, scan_roots\nfrom devclean.ui import app\n\n\ndef _rules_with_additional(path: Path) -> UserRules:\n    base = default_rules()\n    return UserRules(\n        scan=replace(base.scan, additional_paths=(str(path),)),\n        delete=base.delete,\n        keep=base.keep,\n    )\n\n\ndef _audited_rule() -> ApplicationCleanupRule:\n    return ApplicationCleanupRule(\n        rule_id="test-audited-cache",\n        app_id="test",\n        root_key="TEST",\n        relative_pattern="cache",\n        match_kind=MatchKind.PREFIX,\n        owner=DecisionOwner.TOOL,\n        last_use=LastUseStrategy.FILE_MTIME,\n        rebuild_cost=RebuildCost.LOW,\n        idle_days=7,\n        allow_whole_tree=True,\n        label="Test audited cache",\n    )\n\n\ndef test_explicit_root_can_bypass_only_its_own_skipped_basename(tmp_path: Path) -> None:\n    root = tmp_path / "Documents"\n    nested = root / ".git"\n    root.mkdir()\n    nested.mkdir()\n    visible = root / "visible.bin"\n    hidden = nested / "hidden.bin"\n    visible.write_bytes(b"ok")\n    hidden.write_bytes(b"no")\n\n    records = tuple(\n        scan_roots(\n            (root,),\n            ScanOptions(\n                exact_file_identity=False,\n                skip_directory_names=frozenset({"documents", ".git"}),\n                root_skip_name_overrides=frozenset({str(root)}),\n            ),\n        )\n    )\n    paths = {Path(record.path) for record in records}\n    assert visible in paths\n    assert nested in paths\n    assert hidden not in paths\n\n\ndef test_additional_path_below_pruned_profile_survives_outermost_dedup(\n    tmp_path: Path, monkeypatch\n) -> None:\n    profile = tmp_path / "home"\n    project = profile / "Documents" / "project"\n    project.mkdir(parents=True)\n    monkeypatch.setenv("USERPROFILE", str(profile))\n    rules = _rules_with_additional(project)\n    assert "Documents" in rules.scan.skip_directory_names\n\n    roots = app.scan_targets((), rules=rules)\n\n    assert Path(profile.resolve()) in roots\n    assert Path(project.resolve()) in roots\n\n\ndef test_audited_application_root_below_pruned_ancestor_survives(\n    tmp_path: Path, monkeypatch\n) -> None:\n    profile = tmp_path / "home"\n    audited = profile / "Documents" / "tool-cache"\n    audited.mkdir(parents=True)\n    monkeypatch.setenv("USERPROFILE", str(profile))\n    base = default_rules()\n    known = KnownCleanupRoot(\n        path=audited,\n        category=CleanupCategory.OTHER,\n        policy=CleanupPolicy.VENDOR_MANAGED,\n        label="Audited test cache",\n        delete_root_itself=True,\n        application_rule=_audited_rule(),\n    )\n\n    roots = app.scan_targets((known,), rules=base)\n\n    assert Path(profile.resolve()) in roots\n    assert Path(audited.resolve()) in roots\n\n\ndef test_user_exclusion_still_wins_over_specific_root(\n    tmp_path: Path, monkeypatch\n) -> None:\n    profile = tmp_path / "home"\n    project = profile / "Documents" / "project"\n    project.mkdir(parents=True)\n    monkeypatch.setenv("USERPROFILE", str(profile))\n    base = default_rules()\n    rules = UserRules(\n        scan=replace(\n            base.scan,\n            additional_paths=(str(project),),\n            excluded_paths=(str(project),),\n        ),\n        delete=base.delete,\n        keep=base.keep,\n    )\n\n    roots = app.scan_targets((), rules=rules)\n\n    assert Path(project.resolve()) not in roots\n\n\ndef test_root_override_set_contains_only_selected_specific_roots(tmp_path: Path) -> None:\n    explicit = tmp_path / "Documents"\n    unrelated = tmp_path / "other"\n    explicit.mkdir()\n    unrelated.mkdir()\n    rules = _rules_with_additional(explicit)\n\n    overrides = app._scan_root_skip_name_overrides((explicit, unrelated), (), rules)\n\n    assert app.normalise_path(explicit) in overrides\n    assert app.normalise_path(unrelated) not in overrides\n''', encoding="utf-8")

